<script setup>
import {ref,computed} from 'vue'
import Icon from '../Icon.vue'
import {readConfig,saveConfig,defaultConfig,featureCatalog,effectiveFeature,quotePlan} from './config'
const props=defineProps({member:Object})
const config=ref(readConfig()),tab=ref('Overview'),search=ref(''),reason=ref(''),notice=ref(''),scope=ref('Tenant contract'),from=ref(''),until=ref('')
const tabs=['Overview','Features','Limits','Branding','Billing','Exams','Rewards & games','Integrations','Audit log']
const quote=computed(()=>{try{return quotePlan(Number(config.value.students),config.value.tier,config.value.prices)}catch{return {id:'Invalid',amount:null,remaining:0}}})
const features=computed(()=>featureCatalog.filter(f=>(f.label+' '+f.category).toLowerCase().includes(search.value.toLowerCase())))
function setFeature(item,value){if(item.comingSoon)return;if(scope.value==='Platform lock')config.value.locks[item.key]=!value;else if(scope.value==='Country override')config.value.countryOverrides[item.key]=value;else if(scope.value==='Plan default')config.value.planDefaults[item.key]=value;else config.value.features[item.key]={value,from:from.value,until:until.value}}
function save(){try{if(until.value&&from.value&&Date.parse(until.value)<=Date.parse(from.value))throw Error('Expiry must be after the start date');if(config.value.billing.payg&&!config.value.billing.manualInvoice)throw Error('Postpaid services require a real gateway payment method or approved manual-invoice contract. No card is connected in this preview.');for(const [key,value] of Object.entries(config.value.limits))if(!Number.isInteger(value)||value<1||value>1000000)throw Error('Limits must be positive whole numbers');for(const row of config.value.prices)for(const price of row.prices)if(price!==null&&(!Number.isFinite(price)||price<0))throw Error('Prices must be non-negative');if(!Number.isInteger(config.value.billing.collectionDay)||config.value.billing.collectionDay<1||config.value.billing.collectionDay>28)throw Error('Choose a collection day from 1 to 28');if(!Number.isInteger(config.value.billing.graceDays)||config.value.billing.graceDays<0||config.value.billing.graceDays>90)throw Error('Grace period must be 0–90 days');if(!/^\d{1,2}(,\d{1,2}){0,5}$/.test(config.value.billing.retries))throw Error('Enter up to six retry days separated by commas');for(const p of config.value.payg)if(!Number.isFinite(p.price)||p.price<0)throw Error('Add-on prices must be non-negative');quotePlan(Number(config.value.students),config.value.tier,config.value.prices);saveConfig(config.value,props.member.full_name,reason.value);reason.value='';notice.value='Preview configuration saved. Effective settings update immediately.'}catch(e){notice.value=e.message}}
function reset(key){delete config.value.features[key];notice.value='Tenant override removed from the draft. Save with a reason to record it.'}
</script>
<template><section class="control-center"><div class="page-heading"><div><span class="eyebrow">YOUR PLATFORM, THOUGHTFULLY MANAGED</span><h1>Control room.</h1><p>One place for plans, permissions and every learning community.</p></div><span class="badge violet">Configuration preview</span></div><div class="control-tenant"><span class="stat-icon mint"><Icon name="Building2"/></span><div><strong>{{config.branding.name}}</strong><p>SLDA · {{config.country}} · {{quote.id}} · {{config.students}} active students</p></div><span class="badge peach">Demo tenant</span></div><nav class="control-tabs" aria-label="Platform configuration"><button v-for="t in tabs" :aria-pressed="tab===t" @click="tab=t">{{t}}</button></nav>
<section class="panel control-panel"><template v-if="tab==='Overview'"><span class="eyebrow">EFFECTIVE CONFIGURATION</span><h2>Room for your next chapter.</h2><div class="control-metrics"><article><small>Current plan</small><strong>{{quote.id}}</strong></article><article><small>Monthly plan reference</small><strong>{{quote.amount===null?'Custom':'US$'+quote.amount}}</strong></article><article><small>Active students</small><strong>{{config.students}} / {{quote.max}}</strong></article><article><small>Next tier in</small><strong>{{quote.remaining+1}} students</strong></article></div><p>Archived students do not count. This preview uses a configurable active-student count; production billing requires a verified monthly usage ledger.</p><div class="config-priority">Platform lock → Tenant contract → Country override → Plan default → Global default</div><div class="effective-grid"><article v-for="f in featureCatalog"><strong>{{f.label}}</strong><span :class="['badge',effectiveFeature(f.key,config).value?'green':'peach']">{{effectiveFeature(f.key,config).value?'Enabled':f.comingSoon?'Coming soon':'Off'}}</span><small>{{effectiveFeature(f.key,config).source}}</small></article></div></template>
<template v-if="tab==='Features'"><div class="form-row"><label>Find a capability<input v-model="search" placeholder="Exams, certificates, rewards…"></label><label>Configuration scope<select v-model="scope"><option>Tenant contract</option><option>Country override</option><option>Plan default</option><option>Platform lock</option></select></label></div><div v-if="scope==='Tenant contract'" class="form-row"><label>Effective from<input v-model="from" type="datetime-local"></label><label>Expires at<input v-model="until" type="datetime-local"></label></div><article v-for="f in features" class="feature-row"><div><strong>{{f.label}}</strong><small>{{f.category}} · {{effectiveFeature(f.key,config).source}}</small></div><label class="checkbox-label"><input type="checkbox" :checked="effectiveFeature(f.key,config).value" :disabled="f.comingSoon" @change="setFeature(f,$event.target.checked)">{{f.comingSoon?'Coming soon':'Enabled'}}</label><button v-if="config.features[f.key]" class="text-button" @click="reset(f.key)">Reset override</button></article></template>
<template v-if="tab==='Limits'"><h2>Space to grow, with clear limits.</h2><div class="control-fields"><label v-for="(value,key) in config.limits">{{key.replaceAll('_',' ')}}<input v-model.number="config.limits[key]" type="number" min="1" max="1000000"></label></div><p class="field-help">Assignment uploads default to 15 MB. File permissions and limits must also be enforced by the production backend.</p></template>
<template v-if="tab==='Branding'"><h2>A familiar home for their community.</h2><div class="control-fields"><label>Institute display name<input v-model="config.branding.name" maxlength="120"></label><label>Accent color<input v-model="config.branding.color" type="color"></label><label>Requested custom domain<input v-model="config.branding.domain" placeholder="learn.example.com"></label><label>Support email<input v-model="config.branding.support" type="email"></label></div><p class="field-help">Domain changes remain requests until DNS ownership and TLS are verified. No domain is provisioned by this preview.</p></template>
<template v-if="tab==='Billing'"><h2>Clear pricing, wherever they learn.</h2><div class="control-fields"><label>Billing country<input v-model="config.country" maxlength="80"></label><label>Commercial market tier<select v-model="config.tier"><option v-for="(label,i) in ['A · 40% reference','B · 60% reference','C · 80% reference','D · 100% reference','E · 120% reference']" :value="'ABCDE'[i]">{{label}}</option></select></label><label>Active students (preview)<input v-model.number="config.students" type="number" min="0" max="1000000"></label><label>Grace period · days<input v-model.number="config.billing.graceDays" type="number" min="0" max="90"></label><label>Collection offset after month end · days<input v-model.number="config.billing.collectionDay" type="number" min="0" max="28"></label><label>Retry days<input v-model="config.billing.retries" placeholder="1,3,7"></label></div><p>Calendar-month billing · itemized plan, usage, tax, discounts and credits. Reference prices below are explicit country-tier tables, not automatic currency conversion.</p><div class="table-scroll"><table><thead><tr><th>Plan</th><th>Active students up to</th><th v-for="t in 'ABCDE'">Tier {{t}} · USD</th></tr></thead><tbody><tr v-for="row in config.prices"><td>{{row.id}}</td><td>{{row.id==='Enterprise'?'5,001+':row.max}}</td><td v-for="(_,i) in row.prices"><input v-if="row.id!=='Enterprise'&&row.id!=='Free'" v-model.number="row.prices[i]" :aria-label="row.id+' tier '+'ABCDE'[i]" type="number" min="0" step=".01"><span v-else>{{row.id==='Free'?'Free':'Custom'}}</span></td></tr></tbody></table></div><label class="checkbox-label"><input v-model="config.billing.cardSignup" type="checkbox">Require card at institute signup</label><label class="checkbox-label"><input v-model="config.billing.cardFree" type="checkbox">Require card on Free plan</label><label class="checkbox-label"><input v-model="config.billing.manualInvoice" type="checkbox">Approved enterprise manual invoicing</label><label class="checkbox-label"><input v-model="config.billing.payg" type="checkbox">Enable postpaid / pay-as-you-go services</label><h3>Optional services</h3><div class="control-fields"><label v-for="item in config.payg">{{item.name}} · USD/month<input v-model.number="item.price" type="number" min="0" step=".01"></label></div><p class="field-help">SMS requires a country/provider unit rate and is not priced globally. No card numbers or CVC are collected here. Real charging, invoices, retries and refunds require the gateway and billing ledger.</p></template>
<template v-if="tab==='Exams'"><h2>Assessment, on their terms.</h2><div class="control-fields"><label v-for="(value,key) in config.exam" class="checkbox-label"><input type="checkbox" v-model="config.exam[key]">{{({negative:'Allow negative marking',answers:'Show answers after submission',scheduled:'Schedule result release',ranking:'Show student rankings',randomQuestions:'Randomize questions',randomAnswers:'Randomize answers'})[key]}}</label></div><p>MCQ · multiple answers · true/false · short answer · essay. Native Frappe assessment capabilities stay available; advanced timing, question banks and manual marking workflows need their documented implementation.</p></template>
<template v-if="tab==='Rewards & games'"><h2>Celebrate effort. Make room for joy.</h2><div class="control-fields"><label v-for="(value,key) in config.rewards" class="checkbox-label"><input v-model="config.rewards[key]" type="checkbox">{{key}}</label></div><div class="reward-stickers"><span>🌱<b>Little steps</b></span><span>📚<b>Curious mind</b></span><span>🌟<b>Brave effort</b></span><span>☕<b>Steady focus</b></span></div><p>Rewards are optional. Leaderboards are private by default. The learning-games module can be enabled once each template is ready.</p><div class="effective-grid"><article v-for="game in ['Matching','Flashcards','Speed quiz','Memory match','Word match','True/false challenge']"><strong>{{game}}</strong><span class="badge peach">Template planned</span></article></div></template>
<template v-if="tab==='Integrations'"><h2>Connected, with care.</h2><article v-for="provider in ['payments.lk · merchant sandbox required','WhatsApp · approved templates and consent required','Email · verified outgoing SMTP required','YouTube · teacher OAuth required','External calendar sync · Coming soon','AI tools · Coming soon','Native mobile apps · Coming soon']" class="feature-row"><strong>{{provider}}</strong><span class="badge peach">Not activated here</span></article><p class="field-help">Credentials must be configured in encrypted server settings. Never enter API secrets into this local preview.</p></template>
<template v-if="tab==='Audit log'"><h2>A clear record of every change.</h2><p v-if="!config.audit.length">No saved configuration changes yet.</p><details v-for="item in config.audit" class="audit-entry"><summary>{{new Date(item.at).toLocaleString()}} · {{item.actor}} · {{item.reason}}</summary><pre>{{JSON.stringify({before:item.before,after:item.after},null,2)}}</pre></details><p class="field-help">This browser preview history is editable local data. A production immutable server audit is still required.</p></template>
<div v-if="tab!=='Audit log'" class="control-save"><label>Reason for change<input v-model="reason" maxlength="240" placeholder="Contract reference or reason…"></label><button class="button primary" @click="save">Save preview configuration</button></div><p v-if="notice" role="status" class="field-help">{{notice}}</p></section></section></template>
<style>.control-tenant{display:flex;gap:16px;align-items:center;background:var(--student-card);border:1px solid var(--student-border);border-radius:18px;padding:20px}.control-tenant>div{flex:1}.control-tenant p{font-size:12px;margin-top:6px}.control-tabs{display:flex;flex-direction:row;gap:8px;overflow:auto;padding:25px 0}.control-tabs button{width:auto;flex-shrink:0;white-space:nowrap;padding:11px 16px;border-radius:20px;background:var(--student-card);color:var(--student-ink);border:1px solid var(--student-border);font-size:12px}.control-tabs button[aria-pressed=true]{background:var(--student-soft);border-color:var(--student-accent)}.control-panel{padding:30px}.control-panel>h2{font-size:26px;margin-bottom:22px}.control-panel p{font-size:12px;line-height:1.8}.control-panel label{display:flex;flex-direction:column;font-size:12px;gap:9px;margin:14px 0}.control-panel :is(input:not([type=checkbox]),select){padding:12px;border:1px solid var(--student-border);border-radius:10px;background:var(--student-card);color:var(--student-ink);width:100%}.control-fields,.effective-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:15px}.control-metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:20px;margin:25px 0}.control-metrics article{background:var(--student-soft);padding:22px;border-radius:15px}.control-metrics strong{font-size:24px;display:block;margin-top:13px}.control-metrics small{font-size:11px}.effective-grid{margin-top:24px}.effective-grid article{padding:16px;border:1px solid var(--student-border);border-radius:12px;display:flex;gap:12px;align-items:center;flex-wrap:wrap;font-size:12px}.effective-grid small{flex-basis:100%;font-size:10px}.config-priority{padding:20px;background:var(--student-soft);border-radius:14px;font-size:12px;line-height:1.9}.feature-row{display:flex;align-items:center;gap:18px;border-bottom:1px solid var(--student-border);padding:16px 0;font-size:12px}.feature-row>div{flex:1}.feature-row small{display:block;margin-top:7px;font-size:10px}.control-panel .checkbox-label{flex-direction:row;align-items:center}.control-save{display:flex;align-items:end;gap:20px;margin-top:35px;border-top:1px solid var(--student-border);padding-top:15px}.control-save label{flex:1;margin-bottom:0}.control-panel .table-scroll{overflow:auto}.control-panel td input{min-width:70px}.control-panel th{white-space:nowrap}.audit-entry{padding:18px;border-bottom:1px solid var(--student-border);font-size:12px}.audit-entry pre{max-height:400px;overflow:auto;font-size:11px}.reward-stickers{display:flex;gap:25px;margin:25px 0;flex-wrap:wrap}.reward-stickers>span{font-size:46px;background:var(--student-soft);border-radius:25px;padding:20px;text-align:center}.reward-stickers b{display:block;font-size:11px;margin-top:10px}@media(max-width:800px){.control-metrics{grid-template-columns:1fr 1fr}.control-fields,.effective-grid{grid-template-columns:1fr}.control-save{flex-wrap:wrap}.control-save label{flex-basis:100%}.control-panel{padding:20px}.feature-row{flex-wrap:wrap}}
</style>
